import { useTranslation } from 'react-i18next'
import { LogOut, Globe, User, ChevronDown } from 'lucide-react'
import { clsx } from 'clsx'
import { useAuth } from '@hooks/useAuth'
import { useI18n } from '@hooks/useI18n'
import { useState } from 'react'

interface HeaderProps {
  sidebarCollapsed: boolean
}

export function Header({ sidebarCollapsed }: HeaderProps) {
  const { t, i18n } = useTranslation()
  const { user, logout } = useAuth()
  const { changeLanguage, isZh } = useI18n()
  const [showUserMenu, setShowUserMenu] = useState(false)

  const toggleLanguage = () => {
    changeLanguage(isZh ? 'vi' : 'zh')
  }

  const handleLogout = () => {
    logout()
  }

  const roleLabels = {
    admin: t('roles.admin'),
    supervisor: t('roles.supervisor'),
    user: t('roles.user')
  }

  const roleColors = {
    admin: 'bg-danger text-white',
    supervisor: 'bg-warning text-white',
    user: 'bg-secondary text-white'
  }

  return (
    <header className="sticky top-0 z-30 bg-surface border-b border-gray-200 shadow-sm">
      <div className="flex items-center justify-between px-6 py-3">
        {/* Left side - Breadcrumb placeholder */}
        <div className="flex items-center gap-4">
          <div className={clsx('transition-all duration-300', sidebarCollapsed ? 'ml-0' : '')}>
            <nav className="text-sm text-gray-600">
              <ol className="flex items-center gap-2">
                <li>
                  <span className="text-gray-400">{t('header.breadcrumb')}</span>
                </li>
              </ol>
            </nav>
          </div>
        </div>

        {/* Right side - Actions */}
        <div className="flex items-center gap-3">
          {/* Language Toggle */}
          <button
            onClick={toggleLanguage}
            className="flex items-center gap-2 px-3 py-1.5 text-sm border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
            title={t('header.language')}
          >
            <Globe className="w-4 h-4" />
            <span className="font-medium">{isZh ? '中' : 'VI'}</span>
          </button>

          {/* User Menu */}
          <div className="relative">
            <button
              onClick={() => setShowUserMenu(!showUserMenu)}
              className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-gray-50 transition-colors"
            >
              <div className="w-8 h-8 bg-primary rounded-full flex items-center justify-center text-white font-medium">
                {user?.name.charAt(0).toUpperCase() || <User className="w-4 h-4" />}
              </div>
              <div className="text-left">
                <p className="text-sm font-medium text-gray-900">{user?.name || 'User'}</p>
                <p className="text-xs text-gray-500">
                  {user?.role && roleLabels[user.role]}
                </p>
              </div>
              <ChevronDown className="w-4 h-4 text-gray-400" />
            </button>

            {/* Dropdown Menu */}
            {showUserMenu && (
              <>
                <div
                  className="fixed inset-0 z-10"
                  onClick={() => setShowUserMenu(false)}
                />
                <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-lg border border-gray-200 py-1 z-20">
                  <div className="px-4 py-2 border-b border-gray-100">
                    <p className="text-sm font-medium text-gray-900">{user?.name}</p>
                    <p className="text-xs text-gray-500">{user?.email}</p>
                  </div>
                  <button
                    onClick={handleLogout}
                    className="w-full flex items-center gap-2 px-4 py-2 text-sm text-danger hover:bg-gray-50 transition-colors"
                  >
                    <LogOut className="w-4 h-4" />
                    {t('auth.logout')}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </header>
  )
}

export default Header
