/**
 * Module Configuration — data-driven module definitions.
 *
 * Each module is mapped to one or more sub-tables. Each sub-table declares:
 *   - its API endpoint
 *   - its i18n name key
 *   - its column definitions (used for both DataTable columns and dynamic FormModal fields)
 *
 * Column `type` controls the form input rendered (text/number/date/datetime/boolean/select).
 * Columns flagged with `isJsonDetails: true` (only for `data_json` fields) are hidden from the
 * main DataTable and replaced by a "Details" button that opens a read-only JSON viewer.
 *
 * The config is the single source of truth for the dynamic ModulePage — adding a new
 * sub-table requires only a new entry here.
 */

export type FieldType = 'text' | 'number' | 'date' | 'datetime' | 'boolean' | 'select'

export interface SelectOption {
  value: string
  labelKey: string
}

export interface ColumnConfig {
  /** DB column name (snake_case) */
  key: string
  /** i18n key used for both table header and form label */
  labelKey: string
  /** Form input type. Defaults to 'text'. */
  type?: FieldType
  /** Allow sorting. Defaults to true. */
  sortable?: boolean
  /** Show in search dropdown. Defaults to true. */
  searchable?: boolean
  /** CSS width hint for the column. */
  width?: string
  /** Options used when type === 'select'. */
  options?: SelectOption[]
  /** Mark a `data_json` column so it's hidden from the table and shown as a Details button. */
  isJsonDetails?: boolean
}

export interface SubTableConfig {
  /** Stable id, unique within module (used for tab keys and i18n keys). */
  id: string
  /** Full API path, e.g. '/api/personnel/employees'. */
  endpoint: string
  /** i18n key for the sub-table display name. */
  nameKey: string
  /** Column definitions — rendered as DataTable columns and as form inputs. */
  columns: ColumnConfig[]
}

export interface ModuleConfig {
  id: string
  subTables: SubTableConfig[]
}

