/**
 * Internal bookkeeping columns that are present in every record but must never
 * appear in the table view or the form. Currently only `id` is auto-included
 * by the backend SELECT.
 */
export const HIDDEN_COLUMNS = new Set(['id', 'created_at', 'updated_at', 'deleted_at'])

/**
 * Helper: returns all visible (non-hidden, non-data_json) columns.
 * Useful for building the DataTable columns array and the form field list.
 */
export function getVisibleColumns(sub: SubTableConfig): ColumnConfig[] {
  return sub.columns.filter(c => !c.isJsonDetails && !HIDDEN_COLUMNS.has(c.key))
}

/**
 * Helper: returns the JSON-details column config if the sub-table has one.
 */
export function getJsonDetailsColumn(sub: SubTableConfig): ColumnConfig | undefined {
  return sub.columns.find(c => c.isJsonDetails)
}
