import { useTranslation } from 'react-i18next'
import { STORAGE_KEYS } from '@lib/constants'

interface UseI18nReturn {
  t: (key: string, options?: any) => string
  i18n: any
  language: string
  changeLanguage: (lng: 'zh' | 'vi') => void
  isZh: boolean
  isVi: boolean
}

export function useI18n(): UseI18nReturn {
  const { t, i18n } = useTranslation()

  const changeLanguage = (lng: 'zh' | 'vi') => {
    i18n.changeLanguage(lng)
    localStorage.setItem(STORAGE_KEYS.language, lng)
  }

  return {
    t,
    i18n,
    language: i18n.language,
    changeLanguage,
    isZh: i18n.language === 'zh',
    isVi: i18n.language === 'vi'
  }
}

// Helper to get current language
export const getCurrentLanguage = (): 'zh' | 'vi' => {
  const stored = localStorage.getItem(STORAGE_KEYS.language)
  return (stored === 'zh' || stored === 'vi') ? stored as 'zh' | 'vi' : 'zh'
}

// Helper to toggle language
export const toggleLanguage = (): 'zh' | 'vi' => {
  const current = getCurrentLanguage()
  const next = current === 'zh' ? 'vi' : 'zh'
  localStorage.setItem(STORAGE_KEYS.language, next)
  return next
}

export default useI18n
