import { LucideIcon } from 'lucide-react'
import { clsx } from 'clsx'

interface KPICardProps {
  title: string
  value: string | number
  icon: LucideIcon
  trend?: number
  trendLabel?: string
  color?: 'primary' | 'secondary' | 'accent' | 'warning' | 'danger'
  className?: string
  onClick?: () => void
}

const colorVariants = {
  primary: 'bg-primary text-white',
  secondary: 'bg-secondary text-white',
  accent: 'bg-accent text-white',
  warning: 'bg-warning text-white',
  danger: 'bg-danger text-white'
}

export function KPICard({
  title,
  value,
  icon: Icon,
  trend,
  trendLabel,
  color = 'primary',
  className,
  onClick
}: KPICardProps) {
  const isPositive = trend && trend > 0
  const isNegative = trend && trend < 0

  return (
    <div
      className={clsx(
        'bg-surface rounded-xl shadow-card p-6 border border-gray-100',
        'hover:shadow-card-hover transition-shadow duration-200',
        onClick && 'cursor-pointer',
        className
      )}
      onClick={onClick}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <p className="text-sm font-medium text-gray-600 mb-1">{title}</p>
          <p className="text-3xl font-heading font-bold text-gray-900">{value}</p>
          
          {trend !== undefined && (
            <div className="mt-2 flex items-center gap-2">
              <span
                className={clsx(
                  'text-sm font-medium',
                  isPositive ? 'text-accent' : isNegative ? 'text-danger' : 'text-gray-500'
                )}
              >
                {isPositive ? '+' : ''}{trend}%
              </span>
              {trendLabel && (
                <span className="text-xs text-gray-500">{trendLabel}</span>
              )}
            </div>
          )}
        </div>

        <div
          className={clsx(
            'p-3 rounded-lg',
            colorVariants[color]
          )}
        >
          <Icon className="w-6 h-6" />
        </div>
      </div>
    </div>
  )
}

export default KPICard
