import { useState, useEffect, useMemo, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { clsx } from 'clsx'
import { Eye, AlertCircle, X, Search } from 'lucide-react'
import apiClient from '@lib/api'
import { DataTable } from '@components/DataTable'
import { FormModal } from '@components/FormModal'
import { useAuth } from '@hooks/useAuth'
import { MODULES, TABLE_CONFIG } from '@lib/constants'
import {
  MODULE_CONFIG,
  getVisibleColumns,
  getJsonDetailsColumn,
  ColumnConfig,
  SubTableConfig
} from '@lib/module-config'

interface ModulePageProps {
  moduleId: string
}

interface PaginatedResponse {
  data: Record<string, any>[]
  total: number
  page: number
  limit: number
}

// Mirror of DataTable's internal Column<T> type — re-declared here because
// DataTable does not export it.
interface DataTableColumn<T> {
  key: keyof T | string
  label: string
  sortable?: boolean
  render?: (item: T) => React.ReactNode
  width?: string
}

// Row type the DataTable expects: must have a string `id`.
type DataRow = { id: string; [key: string]: any }

/**
 * Data-driven module page. Reads its sub-table definitions from MODULE_CONFIG
 * and renders a tabbed (when >1 sub-table) data grid backed by the real API.
 *
 *  - List fetch: GET /api/{module}/{sub} with page/limit/search/searchCol.
 *  - Create:     POST /api/{module}/{sub}
 *  - Update:     PUT  /api/{module}/{sub}/{id}
 *  - Delete:     DELETE /api/{module}/{sub}/{id} (soft delete)
 *  - data_json:  rendered as a "Details" button opening a read-only JSON modal.
 *  - Role gate:  admin can CRUD; supervisor/user are read-only.
 */
export function ModulePage({ moduleId }: ModulePageProps) {
  const { t, i18n } = useTranslation()
  const { user } = useAuth()
  const isAdmin = user?.role === 'admin'

  const moduleDef = MODULE_CONFIG[moduleId]
  const moduleMeta = MODULES.find(m => m.id === moduleId)
  const moduleName = moduleMeta
    ? (i18n.language === 'zh' ? moduleMeta.nameZh : moduleMeta.nameVi)
    : moduleId

  // -----------------------------------------------------------------
  // Sub-table selection
  // -----------------------------------------------------------------
  const [activeSubTableId, setActiveSubTableId] = useState<string>(
    moduleDef?.subTables[0]?.id ?? ''
  )
  const activeSubTable: SubTableConfig | undefined = useMemo(
    () => moduleDef?.subTables.find(s => s.id === activeSubTableId),
    [moduleDef, activeSubTableId]
  )

  // -----------------------------------------------------------------
  // Data state
  // -----------------------------------------------------------------
  const [rows, setRows] = useState<DataRow[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(false)
  const [loadError, setLoadError] = useState<string | null>(null)

  // Backend-driven search/pagination
  const [searchTerm, setSearchTerm] = useState('')
  const [searchCol, setSearchCol] = useState<string>('')
  const [page, setPage] = useState(1)
  const [pageSize] = useState(TABLE_CONFIG.defaultPageSize)

  // -----------------------------------------------------------------
  // CRUD modal state
  // -----------------------------------------------------------------
  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<'add' | 'edit'>('add')
  const [formRecord, setFormRecord] = useState<Record<string, any> | null>(null)
  const [formValues, setFormValues] = useState<Record<string, any>>({})
  const [formLoading, setFormLoading] = useState(false)
  const [formError, setFormError] = useState<string | null>(null)

  // -----------------------------------------------------------------
  // data_json details modal
  // -----------------------------------------------------------------
  const [detailsOpen, setDetailsOpen] = useState(false)
  const [detailsRecord, setDetailsRecord] = useState<Record<string, any> | null>(null)

  // -----------------------------------------------------------------
  // Visible columns + JSON details flag for the active sub-table
  // -----------------------------------------------------------------
  const visibleColumns = useMemo(
    () => (activeSubTable ? getVisibleColumns(activeSubTable) : []),
    [activeSubTable]
  )
  const jsonDetailsCol = useMemo(
    () => (activeSubTable ? getJsonDetailsColumn(activeSubTable) : undefined),
    [activeSubTable]
  )

  // Reset paging & data when the active sub-table changes
  useEffect(() => {
    setPage(1)
    setSearchTerm('')
    setSearchCol('')
    setRows([])
    setTotal(0)
    setLoadError(null)
  }, [activeSubTableId])

  // -----------------------------------------------------------------
  // Data fetch
  // -----------------------------------------------------------------
  const fetchData = useCallback(async () => {
    if (!activeSubTable) return
    setLoading(true)
    setLoadError(null)
    try {
      const params: Record<string, any> = { page, limit: pageSize }
      if (searchTerm.trim()) {
        params.search = searchTerm.trim()
        if (searchCol) params.searchCol = searchCol
      }
      const res = await apiClient.get<PaginatedResponse>(activeSubTable.endpoint, {
        params
      })
      const payload = res.data
      const rawRows = Array.isArray(payload?.data) ? payload.data : []
      // Stringify id for DataTable's React key requirement (sqlite id is numeric)
      const normalized = rawRows.map(r => ({ ...r, id: String(r.id) }))
      setRows(normalized)
      setTotal(typeof payload?.total === 'number' ? payload.total : normalized.length)
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      console.error('[ModulePage] fetch failed:', msg)
      setLoadError(t('errors.load_failed'))
      setRows([])
      setTotal(0)
    } finally {
      setLoading(false)
    }
  }, [activeSubTable, page, pageSize, searchTerm, searchCol, t])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  // -----------------------------------------------------------------
  // Build DataTable columns (bilingual labels)
  // -----------------------------------------------------------------
  const tableColumns: DataTableColumn<DataRow>[] = useMemo(() => {
    const cols: DataTableColumn<DataRow>[] = visibleColumns.map(col => ({
      key: col.key,
      label: t(col.labelKey),
      sortable: col.sortable !== false,
      width: col.width
    }))
    // Append a "Details" button column for sub-tables that have a data_json field
    if (jsonDetailsCol) {
      cols.push({
        key: '__details__',
        label: t('common.details'),
        sortable: false,
        render: (item: DataRow) => (
          <button
            type="button"
            onClick={() => openDetailsForRow(item)}
            className="inline-flex items-center gap-1 text-secondary hover:text-primary transition-colors text-sm"
          >
            <Eye className="w-4 h-4" />
            {t('common.view_details')}
          </button>
        )
      })
    }
    return cols
  }, [visibleColumns, jsonDetailsCol, t])

  // -----------------------------------------------------------------
  // CRUD handlers
  // -----------------------------------------------------------------
  const openAddForm = () => {
    const empty: Record<string, any> = {}
    visibleColumns.forEach(c => {
      empty[c.key] = ''
    })
    setFormValues(empty)
    setFormError(null)
    setFormRecord(null)
    setFormMode('add')
    setFormOpen(true)
  }

  const openEditForm = (item: Record<string, any>) => {
    const values: Record<string, any> = {}
    visibleColumns.forEach(c => {
      const v = item[c.key]
      values[c.key] = v === null || v === undefined ? '' : String(v)
    })
    setFormValues(values)
    setFormError(null)
    setFormRecord(item)
    setFormMode('edit')
    setFormOpen(true)
  }

  const closeForm = () => {
    if (formLoading) return
    setFormOpen(false)
    setFormError(null)
  }

  const submitForm = async () => {
    if (!activeSubTable) return
    setFormLoading(true)
    setFormError(null)
    try {
      const payload: Record<string, any> = {}
      visibleColumns.forEach(c => {
        const raw = formValues[c.key]
        if (raw === '' || raw === undefined || raw === null) return // skip empty -> null
        payload[c.key] = raw
      })
      if (formMode === 'add') {
        await apiClient.post(activeSubTable.endpoint, payload)
      } else if (formRecord) {
        await apiClient.put(`${activeSubTable.endpoint}/${formRecord.id}`, payload)
      }
      setFormOpen(false)
      await fetchData()
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      console.error('[ModulePage] save failed:', msg)
      setFormError(msg || t('form.submit_failed'))
    } finally {
      setFormLoading(false)
    }
  }

  const handleDelete = async (item: Record<string, any>) => {
    if (!activeSubTable) return
    if (!window.confirm(t('module.delete_confirm'))) return
    try {
      await apiClient.delete(`${activeSubTable.endpoint}/${item.id}`)
      await fetchData()
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      console.error('[ModulePage] delete failed:', msg)
      setLoadError(msg)
    }
  }

  const openDetailsForRow = (item: Record<string, any>) => {
    setDetailsRecord(item)
    setDetailsOpen(true)
  }

  // -----------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------
  if (!moduleDef) {
    return (
      <div className="p-6 bg-red-50 border border-red-200 rounded text-red-700">
        <AlertCircle className="inline w-5 h-5 mr-2" />
        Unknown module: <code className="font-mono">{moduleId}</code>
      </div>
    )
  }

  const activeSubTableName = activeSubTable ? t(activeSubTable.nameKey) : ''

  return (
    <div className="space-y-6">
      {/* ---------------- Page header ---------------- */}
      <div className="flex items-start justify-between">
        <div>
          <h1 className="text-2xl font-heading font-bold text-gray-900">{moduleName}</h1>
          <p className="text-sm text-gray-600 mt-1">
            {t('module.page_subtitle', { module: moduleName })}
          </p>
        </div>
        {!isAdmin && (
          <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-medium bg-yellow-50 text-yellow-700 border border-yellow-200">
            <Eye className="w-3.5 h-3.5" />
            {t('module.read_only_notice')}
          </span>
        )}
      </div>

      {/* ---------------- Sub-table tabs ---------------- */}
      {moduleDef.subTables.length > 1 && (
        <div className="border-b border-gray-200">
          <nav className="-mb-px flex space-x-6 overflow-x-auto">
            {moduleDef.subTables.map(sub => {
              const isActive = sub.id === activeSubTableId
              return (
                <button
                  key={sub.id}
                  type="button"
                  onClick={() => setActiveSubTableId(sub.id)}
                  className={clsx(
                    'py-2 px-1 border-b-2 font-medium text-sm whitespace-nowrap transition-colors',
                    isActive
                      ? 'border-primary text-primary'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  )}
                >
                  {t(sub.nameKey)}
                </button>
              )
            })}
          </nav>
        </div>
      )}

      {/* ---------------- Backend-driven search row ---------------- */}
      <div className="flex flex-col sm:flex-row sm:items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder={t('module.search_placeholder', { subtable: activeSubTableName })}
            value={searchTerm}
            onChange={e => {
              setSearchTerm(e.target.value)
              setPage(1)
            }}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent text-sm"
          />
          {searchTerm && (
            <button
              type="button"
              onClick={() => {
                setSearchTerm('')
                setPage(1)
              }}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
        <select
          value={searchCol}
          onChange={e => {
            setSearchCol(e.target.value)
            setPage(1)
          }}
          className="border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
        >
          <option value="">{t('common.search')}...</option>
          {visibleColumns
            .filter(c => c.searchable !== false)
            .map(c => (
              <option key={c.key} value={c.key}>
                {t(c.labelKey)}
              </option>
            ))}
        </select>
      </div>

      {/* ---------------- Main data table ---------------- */}
      <div className="relative">
        <DataTable
          columns={tableColumns}
          data={rows}
          loading={loading}
          total={total}
          onAdd={isAdmin ? openAddForm : undefined}
          onEdit={isAdmin ? openEditForm : undefined}
          onDelete={isAdmin ? handleDelete : undefined}
          searchPlaceholder={t('module.search_placeholder', {
            subtable: activeSubTableName
          })}
        />

        {/* data_json Details button overlay */}
        {jsonDetailsCol && (
          <div className="mt-3 text-xs text-gray-500 flex items-center gap-2">
            <Eye className="w-3.5 h-3.5" />
            <span>
              {t('common.details')}: {t(jsonDetailsCol.labelKey)}
            </span>
          </div>
        )}
      </div>

      {/* Load error banner */}
      {loadError && (
        <div className="flex items-start gap-3 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700">
          <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
          <span className="flex-1">{loadError}</span>
          <button
            type="button"
            onClick={() => setLoadError(null)}
            className="text-red-500 hover:text-red-700"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* ---------------- Details modal (for data_json) ---------------- */}
      <FormModal
        isOpen={detailsOpen}
        onClose={() => setDetailsOpen(false)}
        title={jsonDetailsCol ? t(jsonDetailsCol.labelKey) : t('common.details')}
        size="lg"
      >
        {detailsRecord && jsonDetailsCol && (
          <JsonDetails value={detailsRecord[jsonDetailsCol.key]} />
        )}
      </FormModal>

      {/* ---------------- Add/Edit form modal ---------------- */}
      <FormModal
        isOpen={formOpen}
        onClose={closeForm}
        title={
          formMode === 'add'
            ? t('module.form_add_title', { subtable: activeSubTableName })
            : t('module.form_edit_title', { subtable: activeSubTableName })
        }
        onSubmit={submitForm}
        submitLabel={formMode === 'add' ? t('common.add') : t('common.save')}
        isLoading={formLoading}
        size="lg"
      >
        {formError && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 flex items-start gap-2">
            <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
            <span>{formError}</span>
          </div>
        )}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {visibleColumns.map(col => (
            <div key={col.key} className="flex flex-col">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t(col.labelKey)}
              </label>
              <DynamicField
                column={col}
                value={formValues[col.key] ?? ''}
                onChange={v => setFormValues(prev => ({ ...prev, [col.key]: v }))}
              />
            </div>
          ))}
        </div>
      </FormModal>
    </div>
  )
}

/**
 * Read-only pretty-printed JSON viewer used by the data_json details modal.
 */
function JsonDetails({ value }: { value: unknown }) {
  let formatted: string
  if (value === null || value === undefined || value === '') {
    formatted = '(empty)'
  } else if (typeof value === 'string') {
    try {
      formatted = JSON.stringify(JSON.parse(value), null, 2)
    } catch {
      formatted = value
    }
  } else {
    try {
      formatted = JSON.stringify(value, null, 2)
    } catch {
      formatted = String(value)
    }
  }
  return (
    <pre className="bg-gray-50 border border-gray-200 rounded-lg p-4 overflow-x-auto text-xs font-mono text-gray-800 max-h-96">
      {formatted}
    </pre>
  )
}

interface DynamicFieldProps {
  column: ColumnConfig
  value: any
  onChange: (v: any) => void
}

/**
 * Renders the appropriate form input based on ColumnConfig.type.
 *  - 'text'     → <input type="text">
 *  - 'number'   → <input type="number">
 *  - 'date'     → <input type="date">
 *  - 'datetime' → <input type="datetime-local"> (converts SQLite "YYYY-MM-DD HH:MM:SS")
 *  - 'select'   → <select> with options
 */
function DynamicField({ column, value, onChange }: DynamicFieldProps) {
  const { t } = useTranslation()
  const baseInput =
    'w-full px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent text-sm'

  switch (column.type) {
    case 'number':
      return (
        <input
          type="number"
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          className={baseInput}
        />
      )
    case 'date':
      return (
        <input
          type="date"
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          className={baseInput}
        />
      )
    case 'datetime':
      // SQLite returns "YYYY-MM-DD HH:MM:SS"; HTML datetime-local needs "YYYY-MM-DDTHH:MM"
      const dtValue =
        typeof value === 'string' && value.length >= 16
          ? value.slice(0, 16).replace(' ', 'T')
          : (value ?? '')
      return (
        <input
          type="datetime-local"
          value={dtValue}
          onChange={e => {
            // Convert back to SQLite-friendly "YYYY-MM-DD HH:MM:SS"
            const v = e.target.value
            onChange(v ? v.replace('T', ' ') + ':00' : '')
          }}
          className={baseInput}
        />
      )
    case 'select':
      return (
        <select
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          className={baseInput}
        >
          <option value="">--</option>
          {column.options?.map(opt => (
            <option key={opt.value} value={opt.value}>
              {t(opt.labelKey)}
            </option>
          ))}
        </select>
      )
    case 'boolean':
      return (
        <select
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          className={baseInput}
        >
          <option value="">--</option>
          <option value="Y">{t('options.yesno.Y')}</option>
          <option value="N">{t('options.yesno.N')}</option>
        </select>
      )
    case 'text':
    default:
      // Multi-line for long text fields
      const longText =
        column.key === 'remarks' ||
        column.key === 'remark' ||
        column.key === 'description' ||
        column.key === 'problem_desc' ||
        column.key === 'root_cause' ||
        column.key === 'corrective_action' ||
        column.key === 'task_desc' ||
        column.key === 'address' ||
        column.key === 'scrap_reason' ||
        column.key === 'recommended_action' ||
        column.key === 'handling' ||
        column.key === 'work_content' ||
        column.key === 'control_measure' ||
        column.key === 'supervisor_comment'
      if (longText) {
        return (
          <textarea
            value={value ?? ''}
            onChange={e => onChange(e.target.value)}
            rows={3}
            className={baseInput}
          />
        )
      }
      return (
        <input
          type="text"
          value={value ?? ''}
          onChange={e => onChange(e.target.value)}
          className={baseInput}
        />
      )
  }
}

export default ModulePage
