import axios, { AxiosInstance, AxiosError, InternalAxiosRequestConfig } from 'axios'
import { API_BASE_URL, API_TIMEOUT, ENDPOINTS, STORAGE_KEYS } from './constants'
import { ApiError } from '../types/index'

// Create axios instance
const apiClient: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  timeout: API_TIMEOUT,
  headers: {
    'Content-Type': 'application/json'
  }
})

// Request interceptor - add JWT token
apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = localStorage.getItem(STORAGE_KEYS.authToken)
    if (token && config.headers) {
      config.headers.Authorization = `Bearer ${token}`
    }
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// Response interceptor - handle 401 errors
apiClient.interceptors.response.use(
  (response) => response,
  (error: AxiosError<ApiError>) => {
    if (error.response?.status === 401) {
      // Clear auth and redirect to login
      localStorage.removeItem(STORAGE_KEYS.authToken)
      localStorage.removeItem(STORAGE_KEYS.user)
      
      // Only redirect if not already on login page
      if (!window.location.pathname.includes('/login')) {
        window.location.href = '/npi-checklist/login'
      }
    }
    return Promise.reject(error)
  }
)

// API service methods
export const api = {
  // Auth
  login: (username: string, password: string) => 
    apiClient.post(ENDPOINTS.login, { username, password }),
  
  logout: () => 
    apiClient.post(ENDPOINTS.logout),
  
  // User
  getProfile: () => 
    apiClient.get(ENDPOINTS.userProfile),
  
  // Dashboard
  getKPI: () => 
    apiClient.get(ENDPOINTS.kpi),
  
  getCharts: () => 
    apiClient.get(ENDPOINTS.charts),
  
  // Generic CRUD operations
  getAll: <T>(endpoint: string, params?: any) => 
    apiClient.get<T[]>(endpoint, { params }),
  
  getById: <T>(endpoint: string, id: string) => 
    apiClient.get<T>(`${endpoint}/${id}`),
  
  create: <T>(endpoint: string, data: any) => 
    apiClient.post<T>(endpoint, data),
  
  update: <T>(endpoint: string, id: string, data: any) => 
    apiClient.put<T>(`${endpoint}/${id}`, data),
  
  delete: (endpoint: string, id: string) => 
    apiClient.delete(`${endpoint}/${id}`)
}

export default apiClient
