import i18n from 'i18next'
import { initReactI18next } from 'react-i18next'
import zh from './zh.json'
import vi from './vi.json'

const resources = {
  zh: { translation: zh },
  vi: { translation: vi }
}

i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: 'zh',
    fallbackLng: 'zh',
    interpolation: {
      escapeValue: false
    },
    react: {
      useSuspense: false
    }
  })

export default i18n
