import { useState, useEffect } from 'react'
import { Link, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { 
  ChevronLeft, 
  ChevronRight,
  LayoutDashboard,
  Users,
  CalendarCheck,
  FileText,
  FolderKanban,
  Clock,
  AlertTriangle,
  ClipboardCheck,
  Trash2,
  GraduationCap,
  Scale,
  Package,
  FileCheck,
  BookOpen,
  type LucideIcon
} from 'lucide-react'
import { clsx } from 'clsx'
import { MODULES } from '@lib/constants'
import { STORAGE_KEYS } from '@lib/constants'

const iconMap: Record<string, LucideIcon> = {
  LayoutDashboard,
  Users,
  CalendarCheck,
  FileText,
  FolderKanban,
  Clock,
  AlertTriangle,
  ClipboardCheck,
  Trash2,
  GraduationCap,
  Scale,
  Package,
  FileCheck,
  BookOpen
}

export function Sidebar() {
  const location = useLocation()
  const { i18n } = useTranslation()
  const [collapsed, setCollapsed] = useState(() => {
    const stored = localStorage.getItem(STORAGE_KEYS.sidebarCollapsed)
    return stored === 'true'
  })

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.sidebarCollapsed, String(collapsed))
  }, [collapsed])

  const toggleSidebar = () => setCollapsed(!collapsed)

  const currentPath = location.pathname

  return (
    <aside
      className={clsx(
        'fixed left-0 top-0 h-full bg-primary text-white transition-all duration-300 ease-in-out z-40',
        collapsed ? 'w-sidebar-collapsed' : 'w-sidebar-expanded'
      )}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-primary-light">
        {!collapsed && (
          <h1 className="text-lg font-heading font-semibold truncate">
            SmartForge 智造工坊
          </h1>
        )}
        <button
          onClick={toggleSidebar}
          className="p-1 hover:bg-primary-light rounded transition-colors"
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? (
            <ChevronRight className="w-5 h-5" />
          ) : (
            <ChevronLeft className="w-5 h-5" />
          )}
        </button>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto py-4">
        <ul className="space-y-1 px-2">
          {/* Dashboard */}
          <li>
            <Link
              to="/dashboard"
              className={clsx(
                'flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
                currentPath === '/dashboard'
                  ? 'bg-primary-light'
                  : 'hover:bg-primary-light/50',
                collapsed && 'justify-center'
              )}
            >
              <LayoutDashboard className="w-5 h-5 flex-shrink-0" />
              {!collapsed && (
                <span className="text-sm font-medium">{i18n.t('nav.dashboard')}</span>
              )}
            </Link>
          </li>

          {/* Modules */}
          {MODULES.map((module) => {
            const Icon = iconMap[module.icon] || LayoutDashboard
            const isActive = currentPath.startsWith(module.path)

            return (
              <li key={module.id}>
                <Link
                  to={module.path}
                  className={clsx(
                    'flex items-center gap-3 px-3 py-2 rounded-lg transition-colors',
                    isActive
                      ? 'bg-primary-light'
                      : 'hover:bg-primary-light/50',
                    collapsed && 'justify-center'
                  )}
                >
                  <Icon className="w-5 h-5 flex-shrink-0" />
                  {!collapsed && (
                    <span className="text-sm font-medium truncate">
                      {i18n.language === 'zh' ? module.nameZh : module.nameVi}
                    </span>
                  )}
                </Link>
              </li>
            )
          })}
        </ul>
      </nav>

      {/* Footer */}
      <div className="p-4 border-t border-primary-light">
        {!collapsed && (
          <p className="text-xs text-center text-gray-400">
            v1.0.0
          </p>
        )}
      </div>
    </aside>
  )
}

export default Sidebar
