import { useState, FormEvent } from 'react'
import { useNavigate, useLocation, Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { zodResolver } from '@hookform/resolvers/zod'
import { useAuth } from '@hooks/useAuth'
import { useI18n } from '@hooks/useI18n'
import { Globe, Lock, User } from 'lucide-react'
import { clsx } from 'clsx'

const loginSchema = z.object({
  username: z.string().min(1, 'form.required'),
  password: z.string().min(1, 'form.required')
})

type LoginForm = z.infer<typeof loginSchema>

export function Login() {
  const navigate = useNavigate()
  const location = useLocation()
  const { t } = useTranslation()
  const { login, isLoading } = useAuth()
  const { changeLanguage, isZh } = useI18n()
  const [error, setError] = useState<string | null>(null)

  const {
    register,
    handleSubmit,
    formState: { errors }
  } = useForm<LoginForm>({
    resolver: zodResolver(loginSchema)
  })

  const from = (location.state as any)?.from?.pathname || '/dashboard'

  const onSubmit = async (data: LoginForm) => {
    setError(null)
    try {
      await login(data.username, data.password)
      navigate(from, { replace: true })
    } catch (err: any) {
      setError(err.response?.data?.message || t('auth.login_failed'))
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary via-primary-light to-secondary p-4">
      <div className="w-full max-w-md">
        {/* Logo Card */}
        <div className="bg-surface rounded-2xl shadow-card-hover p-8 border border-gray-100">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-primary rounded-xl flex items-center justify-center mx-auto mb-4">
              <Lock className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-2xl font-heading font-bold text-gray-900 mb-2">
              {t('app.name')}
            </h1>
            <p className="text-sm text-gray-600">
              {t('app.description')}
            </p>
          </div>

          {/* Language Toggle */}
          <div className="flex justify-center mb-6">
            <button
              onClick={() => changeLanguage(isZh ? 'vi' : 'zh')}
              className="flex items-center gap-2 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
            >
              <Globe className="w-4 h-4" />
              <span className="text-sm font-medium">{isZh ? '中文' : 'Tiếng Việt'}</span>
            </button>
          </div>

          {/* Login Form */}
          <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
            {/* Username */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t('auth.username')}
              </label>
              <div className="relative">
                <User className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="text"
                  {...register('username')}
                  className={clsx(
                    'w-full pl-10 pr-4 py-2.5 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary',
                    errors.username ? 'border-danger' : 'border-gray-300'
                  )}
                  placeholder={t('auth.username')}
                />
              </div>
              {errors.username && (
                <p className="mt-1 text-sm text-danger">{t(errors.username.message!)}</p>
              )}
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {t('auth.password')}
              </label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                <input
                  type="password"
                  {...register('password')}
                  className={clsx(
                    'w-full pl-10 pr-4 py-2.5 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary',
                    errors.password ? 'border-danger' : 'border-gray-300'
                  )}
                  placeholder={t('auth.password')}
                />
              </div>
              {errors.password && (
                <p className="mt-1 text-sm text-danger">{t(errors.password.message!)}</p>
              )}
            </div>

            {/* Error Message */}
            {error && (
              <div className="p-3 bg-danger/10 border border-danger/20 rounded-lg text-sm text-danger">
                {error}
              </div>
            )}

            {/* Submit Button */}
            <button
              type="submit"
              disabled={isLoading}
              className="w-full py-2.5 bg-primary text-white font-medium rounded-lg hover:bg-primary-light transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isLoading ? t('common.loading') : t('auth.login')}
            </button>
          </form>

          {/* Footer Links */}
          <div className="mt-6 text-center">
            <Link
              to="#"
              className="text-sm text-secondary hover:text-primary transition-colors"
            >
              {t('auth.forgot_password')}
            </Link>
          </div>
        </div>

        {/* Copyright */}
        <p className="text-center text-sm text-white/80 mt-6">
          © 2026 SmartForge. All rights reserved.
        </p>
      </div>
    </div>
  )
}

export default Login
